with filtered as (select *, case when browser in ('Firefox', 'Edge') then 'Tier 1' else 'Other' end as browser_group from sessions where started_at >= timestamp '2023-07-04 00:00:00' and browser is not null) select id, customer_id, device, browser, started_at, row_number() over (partition by customer_id, device order by started_at desc, id) as seq_no, last_value(browser) ignore nulls over w_recent as last_known_browser from filtered where country in ('TH', 'US') window w_recent as (partition by device order by started_at, id rows between unbounded preceding and current row)
